"""Verify a schedule generated by scheduler_v6.py (no files modified)."""
import sys
from collections import Counter
from pathlib import Path
from openpyxl import load_workbook
from ortools.sat.python import cp_model
import scheduler_v6 as v3
import json

def main():
    if len(sys.argv)!=2:
        sys.exit('Usage: python verify_schedule_v6.py "input.xlsx"')
    v3.configure(json.loads(Path("config.json").read_text(encoding="utf-8")))
    bands=v3.load_bands(sys.argv[1]); windows=v3.read_windows(bands)
    expected={b['row']:b for b in bands}; seen=Counter(); errors=[]; groups={d:[] for d in v3.HOURS}
    sheet=load_workbook('schedule_result.xlsx',data_only=True)['日割り']
    for r in list(sheet.values)[1:]:
        day,name,songs,length,*rest=r; row=r[10]; seen[row]+=1
        if row not in expected: errors.append(f'Unknown row: {row}'); continue
        b=expected[row]
        if (name,songs,length)!=(b['name'],b['songs'],b['duration']): errors.append(f'Band data mismatch: {row}')
        if day not in groups: errors.append(f'Unassigned or invalid day: {name}'); continue
        d=day; opts=[(a,z) for dd,a,z in windows[row] if dd==d]
        if not opts: errors.append(f'Availability violation: {name} / {day}')
        groups[d].append((b,opts))
    for row in expected:
        if seen[row]!=1: errors.append(f'Row {row}: expected once, found {seen[row]}')
    unknown=False
    for d,group in groups.items():
        cap=v3.HOURS[d][1]-v3.HOURS[d][0]; used=sum(b['duration'] for b,_ in group)
        if used>cap: errors.append(f'{d}: capacity exceeded')
        model=cp_model.CpModel(); intervals=[]
        for i,(b,opts) in enumerate(group):
            flags=[]; length=b['duration']
            for j,(a,z) in enumerate(opts):
                p=model.NewBoolVar(f'p{i}_{j}'); start=model.NewIntVar(a,z-length,f's{i}_{j}'); flags.append(p)
                intervals.append(model.NewOptionalFixedSizeIntervalVar(start,length,p,f'i{i}_{j}'))
            model.Add(sum(flags)==1)
        model.AddNoOverlap(intervals); solver=cp_model.CpSolver(); solver.parameters.max_time_in_seconds=30
        status=solver.Solve(model); label=solver.StatusName(status)
        if status==cp_model.INFEASIBLE: errors.append(f'{d}: no feasible running order')
        elif status not in (cp_model.OPTIMAL,cp_model.FEASIBLE): unknown=True
        print(f'{d}: {len(group)} bands, {used}/{cap} min, {label}')
    print(f'Expected: {len(bands)} bands; result rows: {sum(seen.values())}')
    for e in errors: print('ERROR:',e)
    print('FAIL' if errors else 'UNKNOWN' if unknown else 'PASS')
    return 1 if errors or unknown else 0
if __name__=='__main__':
    sys.exit(main())
